/* prog26_wildcard_match.c
 *
 * Reimplementation of the original program's observable behaviour.
 *
 * The program matches a pattern containing '*' and '?' wildcards
 * against a text string and prints either "MATCH" or "NO_MATCH".
 * If the usage is incorrect or the strings are too long it prints
 * "USAGE".
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 64   /* maximum allowed length for pattern and text (0‑64) */

int main(int argc, char *argv[])
{
    /* ----- usage checks ------------------------------------------------- */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t p_len = strlen(pattern);
    size_t t_len = strlen(text);

    /* the original binary accepts strings of length < 0x41 (i.e. ≤ 64) */
    if (p_len > MAXLEN || t_len > MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* ----- DP table ------------------------------------------------------ */
    /* dp[i][j] – does pattern[0..i-1] match text[0..j-1] ? */
    bool dp[MAXLEN + 1][MAXLEN + 1] = { false };

    dp[0][0] = true;                     /* empty pattern matches empty text */

    /* first row – pattern empty, can only match empty text */
    for (size_t j = 1; j <= t_len; ++j)
        dp[0][j] = false;

    /* first column – text empty, only a sequence of '*' can match */
    for (size_t i = 1; i <= p_len; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }

    /* fill the rest of the table */
    for (size_t i = 1; i <= p_len; ++i) {
        char pc = pattern[i - 1];
        for (size_t j = 1; j <= t_len; ++j) {
            char tc = text[j - 1];
            if (pc == '*') {
                dp[i][j] = dp[i - 1][j]      /* * matches empty */
                        || dp[i][j - 1];    /* * consumes one character */
            } else if (pc == '?') {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = (pc == tc) && dp[i - 1][j - 1];
            }
        }
    }

    /* ----- result -------------------------------------------------------- */
    if (dp[p_len][t_len])
        puts("MATCH");
    else
        puts("NO_MATCH");

    return 0;
}
